/* One shared header for all XS 2026 pages. */
(()=>{const node=document.currentScript;if(document.querySelector('header.site-header')){node.remove();return;}document.body.insertAdjacentHTML('afterbegin',"<header class=\"site-header\"><div class=\"container header-inner\"><a class=\"brand\" href=\"index.html\" aria-label=\"Xavier Serbia, inicio\"><img src=\"data:image/png;base64,\" alt=\"Xavier Serbia\" width=\"900\" height=\"136\"></a><nav class=\"nav-desktop\" aria-label=\"Principal\"><a href=\"tu-dinero.html\">Tu Dinero</a><a href=\"videos.html\">Videos</a><a href=\"index.html#sobre\">Sobre Xavier</a><a href=\"contacto.html\">Contacto</a></nav><div class=\"header-actions\"><a class=\"btn btn-primary\" href=\"index.html#whatsapp\">Únete al canal</a><button class=\"menu-button\" type=\"button\" aria-label=\"Abrir menú\" aria-expanded=\"false\" aria-controls=\"mobile-menu\"><svg aria-hidden=\"true\" width=\"19\" height=\"19\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M4 7h16M4 12h16M4 17h16\"/></svg> Menú</button></div></div><nav id=\"mobile-menu\" class=\"mobile-menu\" aria-label=\"Móvil\"><div class=\"container mobile-menu-inner\"><a href=\"tu-dinero.html\">Tu Dinero</a><a href=\"videos.html\">Videos</a><a href=\"index.html#sobre\">Sobre Xavier</a><a href=\"contacto.html\">Contacto</a><a class=\"btn btn-primary\" href=\"index.html#whatsapp\">Únete al canal de WhatsApp</a></div></nav></header>");node.remove();if(!/(?:\/|\/index\.html)$/.test(location.pathname)){const btn=document.querySelector('.site-header .menu-button'),menu=document.getElementById('mobile-menu');if(btn&&menu){const close=()=>{menu.classList.remove('open');btn.setAttribute('aria-expanded','false')};btn.addEventListener('click',()=>{const open=menu.classList.toggle('open');btn.setAttribute('aria-expanded',String(open))});menu.querySelectorAll('a').forEach(link=>link.addEventListener('click',close));document.addEventListener('keydown',e=>{if(e.key==='Escape')close()})}}})();